import json, sys
from figs import *
OUT='/home/user/wt-svt5/content/sciences-vie-terre/12-takawwun-al-janin/exercices/'
def mcq(p,opts,key,expl,d,fig=None):
    L='abcd'
    o=[]
    for i,(t,tag) in enumerate(opts):
        x={"id":L[i],"text":t}
        if tag: x["misconceptionTag"]="bio."+tag
        o.append(x)
    return {"type":"mcq","prompt":p+("\n"+fig if fig else ""),"options":o,"correctOption":L[key],"explanation":expl,"difficulty":d}
def matching(p,left,right,pairs,expl,d,fig=None):
    o=[{"id":f"l{i+1}","text":t} for i,t in enumerate(left)]+[{"id":f"r{j+1}","text":t} for j,t in enumerate(right)]
    return {"type":"matching","prompt":p+("\n"+fig if fig else ""),"options":o,"answerKey":{"pairs":[[f"l{i+1}",f"r{j+1}"] for i,j in pairs]},"explanation":expl,"difficulty":d}
def ordering(p,items,order,expl,d):
    L='abcdef'
    o=[{"id":L[i],"text":t} for i,t in enumerate(items)]
    return {"type":"ordering","prompt":p,"options":o,"answerKey":{"order":[L[i] for i in order]},"explanation":expl,"difficulty":d}
def multi(p,items,correct,expl,d):
    L='abcdefgh'
    o=[{"id":L[i],"text":t} for i,t in enumerate(items)]
    return {"type":"multi","prompt":p,"options":o,"answerKey":{"correct":[L[i] for i in correct]},"explanation":expl,"difficulty":d}
def place(q,pos):
    if q["type"]!="mcq" or pos is None: return q
    L='abcd'
    opts=q["options"]; k=L.index(q["correctOption"])
    key=opts.pop(k); opts.insert(pos,key)
    for i,o in enumerate(opts): o["id"]=L[i]
    q["correctOption"]=L[pos]
    return q
def save(name,title,d,mode,xp,coins,order,qs,pos=None,strip_ab=False,diffs=None):
    if diffs:
        for q,x in zip(qs,diffs): q["difficulty"]=x
    if pos: qs=[place(q,p) for q,p in zip(qs,pos)]
    if strip_ab:
        for q in qs: q["explanation"]=q["explanation"].replace("(أ)","أ").replace("(ب)","ب")
    j={"title":title,"difficulty":d,"mode":mode,"xpReward":xp,"rewardCoins":coins,"displayOrder":order,"questions":qs}
    open(OUT+name,'w',encoding='utf-8').write(json.dumps(j,ensure_ascii=False,indent=2)+"\n")

